package com.eia.contract.expert.cashcall;

import com.fasterxml.jackson.annotation.JsonFormat;

import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.util.UUID;

/**
 * A contract cash call: a request for a forward payment on a contract period
 * (SPEC 11.3.4, the Contract {@code CASH_CALL} command).
 *
 * <p>A cash call is a child aggregate of the contract. The call number is
 * generated by the expert ({@code CC-{YEAR}-{SEQ}}) and is unique per tenant and
 * contract. The amount is stored as {@code numeric(19,4)} and exposed as a
 * decimal string (SPEC 10.3); it must be strictly positive. The lifecycle is
 * {@code REQUESTED -> ISSUED -> SETTLED} or {@code REQUESTED -> CANCELLED}, with
 * both terminal statuses immutable. The status values, the period, and the
 * positive amount are enforced by the database as well as by the API.</p>
 */
public record ContractCashCall(
        UUID id,
        UUID tenantId,
        UUID contractId,
        String callNumber,
        LocalDate periodStart,
        LocalDate periodEnd,
        @JsonFormat(shape = JsonFormat.Shape.STRING) BigDecimal amount,
        String currency,
        LocalDate dueDate,
        String status,
        String notes,
        Instant createdAt
) {

    public static ContractCashCall requested(
            UUID tenantId,
            UUID contractId,
            String callNumber,
            LocalDate periodStart,
            LocalDate periodEnd,
            BigDecimal amount,
            String currency,
            LocalDate dueDate,
            String notes) {
        return new ContractCashCall(
                UUID.randomUUID(), tenantId, contractId, callNumber, periodStart, periodEnd,
                amount, currency, dueDate, CashCallStatus.REQUESTED.name(), notes, Instant.now());
    }
}
